    steps = [
        f"讀題定位：圈出「{tag}」，找出作者要讀者接受的主張，以及支持它的資料、理由或反方疑問。",
        f"拆解推進：分清事實、推論、價值判斷與行動要求，檢查資料是否真的支援結論；本題核心是「{explanation}」",
        f"核對正解：選項 {answer_id}「{answer}」能讓論證角色或結論強度與題幹資料相稱。",
        "排除誘答：留意把個案推成全體、把同時發生當成因果、把情感口號當證據，或只刪除反方疑問而沒有回應。",
        "回查論證鏈：用議題—主張—理由—證據—限制／反方—修正結論逐段回看，確認沒有超出證據範圍。",
    ]
    return {"id": f"question-chinese-content-bd-{i}", "subject": "chinese", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-chinese-content-bd"], "difficulty": "medium", "answer": {"value": answer_id, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "公立學校公開國文段考與課程資料；本題只研究公開試題與課程評量的能力結構。", "authoringNote": "依官方語文領域課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫議題主張、段落功能、事實與評價、理由證據、因果、反方、代表性、結論強度、反例及整合論證；未複製原文、選項、篇章、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-chinese-content-bd", "examPatternRefs": refs, "solutionStrategy": "先畫出主張—理由—證據的鏈條，再檢查事實與評價、範圍與代表性、因果與替代解釋；最後加入反方、限制和可執行的評估，讓結論強度與資料相稱。", "solutionSteps": steps}

